CREATE OR REPLACE FUNCTION "public"."expire_old_listings"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  expired_count INTEGER;
BEGIN
  UPDATE public.listings
  SET status = 'expired'
  WHERE expires_at <= NOW()
    AND LOWER(COALESCE(status, '')) NOT IN
        ('expired', 'rejected', 'deleted');

  GET DIAGNOSTICS expired_count = ROW_COUNT;

  RETURN expired_count;
END;
$$;


ALTER FUNCTION "public"."expire_old_listings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nearby_suppliers"("buy_lat" double precision, "buy_lng" double precision, "radius_km" integer DEFAULT 40) RETURNS TABLE("id" "uuid", "title" "text", "wood_species" "text", "phone" "text", "location" "text", "digipin_code" "text", "latitude" double precision, "longitude" double precision, "distance_km" double precision, "is_trusted" boolean)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    b.id, b.title, b.wood_species, b.phone, b.location, b.digipin_code, b.latitude, b.longitude,
    (6371 * acos(cos(radians(buy_lat)) * cos(radians(b.latitude)) * cos(radians(b.longitude) - radians(buy_lng)) + sin(radians(buy_lat)) * sin(radians(b.latitude)))) AS distance_km,
    b.is_trusted
  FROM buyer_requirements b
  WHERE b.status = 'approved' 
    AND b.is_wanted = false 
    AND b.latitude IS NOT NULL 
    AND b.longitude IS NOT NULL
    AND (6371 * acos(cos(radians(buy_lat)) * cos(radians(b.latitude)) * cos(radians(b.longitude) - radians(buy_lng)) + sin(radians(buy_lat)) * sin(radians(b.latitude)))) <= radius_km
  ORDER BY distance_km ASC
  LIMIT 10;
END;
$$;


ALTER FUNCTION "public"."nearby_suppliers"("buy_lat" double precision, "buy_lng" double precision, "radius_km" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_nearby"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE sup RECORD; dist DOUBLE PRECISION;
BEGIN
  FOR sup IN SELECT * FROM suppliers LOOP
    dist := 111.0 * sqrt(power(NEW.latitude - sup.latitude,2) + power(NEW.longitude - sup.longitude,2));
    IF dist <= sup.search_radius_km THEN
      INSERT INTO notifications (listing_id, supplier_id, supplier_phone, distance_km, message)
      VALUES (NEW.listing_id, sup.id, sup.phone, ROUND(dist::numeric,1), '🌲 New ' || NEW.species || ' at ' || NEW.location_village || ' - ' || ROUND(dist::numeric,1) || 'KM from you! Call: ' || NEW.whatsapp_number);
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_nearby"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_users_profile_role"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.role := 'user';
  ELSIF TG_OP = 'UPDATE'
    AND auth.role() IN ('authenticated', 'service_role')
    AND NEW.role IS DISTINCT FROM OLD.role THEN
    RAISE EXCEPTION 'Role changes are not allowed';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_users_profile_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_listing_expiry_14_days"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.created_at IS NULL THEN
    NEW.created_at := NOW();
  END IF;

  IF NEW.expires_at IS NULL THEN
    NEW.expires_at := NEW.created_at + INTERVAL '14 days';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_listing_expiry_14_days"() OWNER TO "postgres";

