CREATE TABLE IF NOT EXISTS "public"."announcements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" NOT NULL,
    "image_url" "text",
    "contact_number" "text",
    "website_url" "text",
    "announcement_type" "text" DEFAULT 'paid'::"text" NOT NULL,
    "is_admin_announcement" boolean DEFAULT false NOT NULL,
    "target_audience" "text" DEFAULT 'all'::"text" NOT NULL,
    "package_days" integer,
    "amount" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'pending_payment'::"text" NOT NULL,
    "rejection_reason" "text",
    "starts_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "announcement_type_rules" CHECK (((("announcement_type" = 'admin'::"text") AND ("is_admin_announcement" = true) AND ("amount" = 0) AND ("package_days" IS NULL)) OR (("announcement_type" = 'paid'::"text") AND ("is_admin_announcement" = false) AND ((("package_days" = 7) AND ("amount" = 149)) OR (("package_days" = 14) AND ("amount" = 249)))))),
    CONSTRAINT "announcements_amount_check" CHECK (("amount" = ANY (ARRAY[0, 149, 249]))),
    CONSTRAINT "announcements_announcement_type_check" CHECK (("announcement_type" = ANY (ARRAY['admin'::"text", 'paid'::"text"]))),
    CONSTRAINT "announcements_package_days_check" CHECK ((("package_days" = ANY (ARRAY[7, 14])) OR ("package_days" IS NULL))),
    CONSTRAINT "announcements_status_check" CHECK (("status" = ANY (ARRAY['pending_payment'::"text", 'pending_approval'::"text", 'approved'::"text", 'active'::"text", 'rejected'::"text", 'expired'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "announcements_target_audience_check" CHECK (("target_audience" = ANY (ARRAY['all'::"text", 'farmers'::"text", 'merchants'::"text", 'sawmills'::"text", 'carpenters'::"text"])))
